#include <iostream>
#include <vector>

class Stack : public std::vector<int> {
    // inherits insert(iterator, value), erase(iterator), operator[](index)...
    // now callers can bypass the stack contract entirely
};

int main() {
    Stack stack;
    stack.push_back(0);
    stack.push_back(1);
    stack.push_back(2);
    stack.insert(stack.begin(), 42);   // inserts at the bottom, not how a stack should work!
    for (int v : stack) std::cout << v << " ";
    std::cout << std::endl;
    return 0;
}

