class Stack:
    def __init__(self):
        self._storage = deque()

    def push(self, item):
        self._storage.append(item)

    def pop(self):
        return self._storage.pop()

    def peek(self):
        return self._storage[-1]

    def is_empty(self):
        return len(self._storage) == 0
    # No insert(index), no getitem(index), callers can't break the invariant


