#include <iostream>
#include <deque>

template <typename T>
class Stack {
private:
    std::deque<T> storage;

public:
    void push(T item) { storage.push_back(item); }
    T pop() { T v = storage.back(); storage.pop_back(); return v; }
    T peek() { return storage.back(); }
    bool isEmpty() { return storage.empty(); }
    // No insert(index), no operator[](index), callers can't break the invariant
};

int main() {
    Stack<int> stack;
    stack.push(1);
    stack.push(2);
    stack.push(3);
    std::cout << "Top: " << stack.peek() << std::endl;
    std::cout << "Popped: " << stack.pop() << std::endl;
    std::cout << "Is empty: " << (stack.isEmpty() ? "true" : "false") << std::endl;
    return 0;
}

