#include <iostream>
#include <memory>

class FlyBehaviour {
public:
    virtual void fly() = 0;
    virtual ~FlyBehaviour() = default;
};

class FlapWings : public FlyBehaviour {
public:
    void fly() override { std::cout << "Flaps wings and flies" << std::endl; }
};

class NoFly : public FlyBehaviour {
public:
    void fly() override { std::cout << "Can't fly" << std::endl; }
};

class Duck {
private:
    std::shared_ptr<FlyBehaviour> flyBehaviour;   // can be changed

public:
    Duck(std::shared_ptr<FlyBehaviour> flyBehaviour) : flyBehaviour(flyBehaviour) {}

    void setFlyBehaviour(std::shared_ptr<FlyBehaviour> fb) {
        flyBehaviour = fb;
    }

    void fly() { flyBehaviour->fly(); }
};

int main() {
    Duck mallard(std::make_shared<FlapWings>());
    mallard.fly();                                        // flaps wings

    mallard.setFlyBehaviour(std::make_shared<NoFly>());   // now it's injured and can't fly
    mallard.fly();                                        // does nothing useful, changed at runtime
    return 0;
}

