#include <iostream>

class Rectangle {
protected:
    int width = 0, height = 0;

public:
    virtual void setWidth(int w)  { width  = w; }
    virtual void setHeight(int h) { height = h; }
    int getWidth() const  { return width; }
    int getHeight() const { return height; }
    virtual ~Rectangle() = default;
};

class Square : public Rectangle {  // "Square is-a Rectangle", sounds right!
public:
    void setWidth(int w) override  { width = height = w; }   // must stay equal
    void setHeight(int h) override { width = height = h; }
};

int main() {
    // Code that works for Rectangle breaks for Square:
    Rectangle* r = new Square();
    r->setWidth(5);
    r->setHeight(10);
    int area = r->getWidth() * r->getHeight();
    std::cout << "Expected area: 50, Actual area: " << area << std::endl;
    std::cout << "LSP violated: " << (area != 50 ? "true" : "false") << std::endl;
    delete r;
    return 0;
}

