#include <iostream>
#include <string>

class Notifier {
public:
    virtual void send(const std::string& msg) { std::cout << "Notifying: " << msg << std::endl; }
    virtual ~Notifier() = default;
};

class EmailNotifier : public Notifier {
public:
    void send(const std::string& msg) override { std::cout << "Email: " << msg << std::endl; }
};

class SmsNotifier : public Notifier {
public:
    void send(const std::string& msg) override { std::cout << "SMS: " << msg << std::endl; }
};

class PushNotifier : public Notifier {
public:
    void send(const std::string& msg) override { std::cout << "Push: " << msg << std::endl; }
};

// What if a user wants email + SMS?
// C++ technically allows multiple inheritance, but combining two concrete
// classes this way leads straight to diamond-problem style ambiguity,
// which is exactly why composition is preferred here.

int main() {
    Notifier* email = new EmailNotifier();
    Notifier* sms = new SmsNotifier();
    email->send("Order shipped");
    sms->send("Order shipped");
    delete email;
    delete sms;
    return 0;
}

