# Define the behaviour as an interface
class SortStrategy:
    def sort(self, data):
        raise NotImplementedError


# Multiple implementations, same interface, different behaviour
class QuickSort(SortStrategy):
    def sort(self, data):
        self._quick_sort(data, 0, len(data) - 1)

    def _quick_sort(self, data, low, high):
        if low < high:
            pivot = data[high]
            i = low - 1
            for j in range(low, high):
                if data[j] < pivot:
                    i += 1
                    data[i], data[j] = data[j], data[i]
            data[i + 1], data[high] = data[high], data[i + 1]
            p = i + 1
            self._quick_sort(data, low, p - 1)
            self._quick_sort(data, p + 1, high)


class MergeSort(SortStrategy):
    def sort(self, data):
        data[:] = self._merge_sort(data)

    def _merge_sort(self, data):
        if len(data) <= 1:
            return data
        mid = len(data) // 2
        left = self._merge_sort(data[:mid])
        right = self._merge_sort(data[mid:])
        return self._merge(left, right)

    def _merge(self, left, right):
        result = []
        i = j = 0
        while i < len(left) and j < len(right):
            if left[i] <= right[j]:
                result.append(left[i])
                i += 1
            else:
                result.append(right[j])
                j += 1
        result.extend(left[i:])
        result.extend(right[j:])
        return result


