import java.util.List;
import java.util.ArrayList;

// Define the behaviour as an interface
interface SortStrategy {
    void sort(List<Integer> data);
}

// Multiple implementations — same interface, different behaviour
class QuickSort implements SortStrategy {
    @Override public void sort(List<Integer> data) { quickSort(data, 0, data.size() - 1); }

    private void quickSort(List<Integer> data, int low, int high) {
        if (low < high) {
            int pivot = data.get(high);
            int i = low - 1;
            for (int j = low; j < high; j++) {
                if (data.get(j) < pivot) {
                    i++;
                    int tmp = data.get(i); data.set(i, data.get(j)); data.set(j, tmp);
                }
            }
            int tmp = data.get(i + 1); data.set(i + 1, data.get(high)); data.set(high, tmp);
            int p = i + 1;
            quickSort(data, low, p - 1);
            quickSort(data, p + 1, high);
        }
    }
}
class MergeSort implements SortStrategy {
    @Override public void sort(List<Integer> data) {
        List<Integer> sorted = mergeSort(data);
        for (int i = 0; i < data.size(); i++) data.set(i, sorted.get(i));
    }

    private List<Integer> mergeSort(List<Integer> list) {
        if (list.size() <= 1) return list;
        int mid = list.size() / 2;
        List<Integer> left = mergeSort(new ArrayList<>(list.subList(0, mid)));
        List<Integer> right = mergeSort(new ArrayList<>(list.subList(mid, list.size())));
        return merge(left, right);
    }

    private List<Integer> merge(List<Integer> left, List<Integer> right) {
        List<Integer> result = new ArrayList<>();
        int i = 0, j = 0;
        while (i < left.size() && j < right.size()) {
            if (left.get(i) <= right.get(j)) result.add(left.get(i++));
            else result.add(right.get(j++));
        }
        while (i < left.size()) result.add(left.get(i++));
        while (j < right.size()) result.add(right.get(j++));
        return result;
    }
}
class BubbleSort implements SortStrategy {
    @Override public void sort(List<Integer> data) {
        int n = data.size();
        for (int i = 0; i < n - 1; i++) {
            for (int j = 0; j < n - 1 - i; j++) {
                if (data.get(j) > data.get(j + 1)) {
                    int tmp = data.get(j);
                    data.set(j, data.get(j + 1));
                    data.set(j + 1, tmp);
                }
            }
        }
    }
}

// Sorter composes a strategy — not inherits one
class DataSorter {
    private SortStrategy strategy;

    public DataSorter(SortStrategy strategy) {
        this.strategy = strategy;
    }

    // Swap strategy at runtime — no class change
    public void setStrategy(SortStrategy strategy) {
        this.strategy = strategy;
    }

    public void sort(List<Integer> data) {
        strategy.sort(data);
    }
}

public class Main {
    public static void main(String[] args) {
        List<Integer> bigList = new ArrayList<>(List.of(5, 3, 8, 1, 9));
        List<Integer> smallList = new ArrayList<>(List.of(4, 2, 1));

        // Usage — different strategies, same DataSorter
        DataSorter sorter = new DataSorter(new QuickSort());
        sorter.sort(bigList);
