#include <iostream>
#include <vector>
#include <memory>

// Define the behaviour as an interface
class SortStrategy {
public:
    virtual void sort(std::vector<int>& data) = 0;
    virtual ~SortStrategy() = default;
};

// Multiple implementations, same interface, different behaviour
class QuickSort : public SortStrategy {
public:
    void sort(std::vector<int>& data) override { quickSort(data, 0, (int)data.size() - 1); }

private:
    void quickSort(std::vector<int>& data, int low, int high) {
        if (low < high) {
            int pivot = data[high];
            int i = low - 1;
            for (int j = low; j < high; j++) {
                if (data[j] < pivot) {
                    i++;
                    std::swap(data[i], data[j]);
                }
            }
            std::swap(data[i + 1], data[high]);
            int p = i + 1;
            quickSort(data, low, p - 1);
            quickSort(data, p + 1, high);
        }
    }
};

class MergeSort : public SortStrategy {
public:
    void sort(std::vector<int>& data) override { data = mergeSort(data); }

private:
    std::vector<int> mergeSort(std::vector<int> data) {
        if (data.size() <= 1) return data;
        size_t mid = data.size() / 2;
        std::vector<int> left = mergeSort(std::vector<int>(data.begin(), data.begin() + mid));
        std::vector<int> right = mergeSort(std::vector<int>(data.begin() + mid, data.end()));
        return merge(left, right);
    }

    std::vector<int> merge(const std::vector<int>& left, const std::vector<int>& right) {
        std::vector<int> result;
        size_t i = 0, j = 0;
        while (i < left.size() && j < right.size()) {
            if (left[i] <= right[j]) result.push_back(left[i++]);
            else result.push_back(right[j++]);
        }
        while (i < left.size()) result.push_back(left[i++]);
        while (j < right.size()) result.push_back(right[j++]);
        return result;
    }
};

class BubbleSort : public SortStrategy {
public:
    void sort(std::vector<int>& data) override {
        size_t n = data.size();
        for (size_t i = 0; i + 1 < n; i++) {
            for (size_t j = 0; j + 1 < n - i; j++) {
                if (data[j] > data[j + 1]) std::swap(data[j], data[j + 1]);
            }
        }
    }
};

// Sorter composes a strategy, not inherits one
class DataSorter {
private:
    std::shared_ptr<SortStrategy> strategy;

public:
    DataSorter(std::shared_ptr<SortStrategy> strategy) : strategy(strategy) {}

    // Swap strategy at runtime, no class change
    void setStrategy(std::shared_ptr<SortStrategy> newStrategy) { strategy = newStrategy; }

    void sort(std::vector<int>& data) { strategy->sort(data); }
};

int main() {
    std::vector<int> bigList = {5, 3, 8, 1, 9};
    std::vector<int> smallList = {4, 2, 1};

    // Usage, different strategies, same DataSorter
    DataSorter sorter(std::make_shared<QuickSort>());
    sorter.sort(bigList);
    std::cout << "Sorted big list: ";
    for (int v : bigList) std::cout << v << " ";
    std::cout << std::endl;

    sorter.setStrategy(std::make_shared<BubbleSort>());  // swap at runtime
    sorter.sort(smallList);
    std::cout << "Sorted small list: ";
    for (int v : smallList) std::cout << v << " ";
    std::cout << std::endl;

    return 0;
}

