    std::string value;

public:
    OrderId(std::string value) : value(value) {}
    std::string toString() const { return value; }
};

class PaymentResult {
private:
    bool success;
    std::string message;
    PaymentResult(bool success, std::string message) : success(success), message(message) {}

public:
    static PaymentResult success(const std::string& message) { return PaymentResult(true, message); }
    std::string toString() const { return (success ? "SUCCESS: " : "FAILED: ") + message; }
};

class DomainException : public std::runtime_error {
public:
    DomainException(const std::string& message) : std::runtime_error(message) {}
};

// Interface, what every payment method must do
class PaymentMethod {
public:
    virtual PaymentResult pay(const Money& amount) = 0;
    virtual bool isAvailable() = 0;
    virtual ~PaymentMethod() = default;
};

// Each method is its own class
class CreditCardPayment : public PaymentMethod {
private:
    std::string cardNumber;

public:
    CreditCardPayment(std::string cardNumber) : cardNumber(cardNumber) {}

    PaymentResult pay(const Money& amount) override {
        // charge the card
        return PaymentResult::success("Charged card ending " + cardNumber.substr(cardNumber.size() - 4));
    }
    bool isAvailable() override { return true; }
};

class UpiPayment : public PaymentMethod {
private:
    std::string upiId;

public:
    UpiPayment(std::string upiId) : upiId(upiId) {}

    PaymentResult pay(const Money& amount) override {
        // trigger UPI
        return PaymentResult::success("UPI payment via " + upiId);
    }
    bool isAvailable() override { return true; }
};

// Order composes a PaymentMethod, doesn't inherit it
class Order {
private:
    OrderId id;
    Money total;
    std::shared_ptr<PaymentMethod> paymentMethod;   // HAS-A PaymentMethod

public:
    Order(OrderId id, Money total, std::shared_ptr<PaymentMethod> paymentMethod)
        : id(id), total(total), paymentMethod(paymentMethod) {}

    PaymentResult checkout() {
        if (!paymentMethod->isAvailable())
            throw DomainException("Payment method not available");
        return paymentMethod->pay(total);
    }

    void setPaymentMethod(std::shared_ptr<PaymentMethod> method) { paymentMethod = method; }
};

int main() {
    Order order(OrderId("ORD-1001"), Money(150000), std::make_shared<CreditCardPayment>("4111111111111111"));
    std::cout << order.checkout().toString() << std::endl;

    order.setPaymentMethod(std::make_shared<UpiPayment>("user@bank"));
    std::cout << order.checkout().toString() << std::endl;

    return 0;
}

